<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GoldHen Store AJ · v3.3</title><script src="https://cdn.tailwindcss.com"></script><style>body{background:#060913}.card{transition:transform .2s,border-color .2s}.card:hover{transform:translateY(-3px);border-color:rgb(34 211 238/.35)}</style></head>
<body class="min-h-screen bg-[#060913] text-white p-4"><main class="mx-auto max-w-6xl"><header class="mb-5 flex flex-wrap items-center justify-between gap-3"><div><h1 class="text-xl font-black">GoldHen Store AJ <span class="text-cyan-300">v3.3</span></h1><p class="text-xs text-cyan-300">Catálogo autorizado · instalación directa por RPI</p></div><div class="flex gap-2"><a href="../index.php" class="rounded-xl bg-white/5 px-4 py-2 text-xs text-gray-200">← Manager</a><button onclick="cargarCatalogo()" class="rounded-xl bg-cyan-500/15 px-4 py-2 text-xs text-cyan-100">↻ Actualizar</button></div></header>
<section class="mb-4 rounded-3xl border border-amber-500/25 bg-amber-500/5 p-4"><div class="flex gap-3"><span class="text-amber-300">⚠</span><div><b class="text-sm text-amber-100">Antes de usar la Store</b><p class="mt-1 text-[11px] leading-relaxed text-amber-100/75">Abre Remote Package Installer (RPI) en la PS4 y comprueba el puerto que muestra su notificación. Configura abajo la IP de la consola y el puerto de RPI antes de enviar un paquete. La Store envía la URL al instalador: no descarga el PKG al teléfono.</p></div></div></section>
<section class="mb-5 rounded-3xl border border-cyan-500/20 bg-white/[.035] p-4"><div class="mb-3 flex items-center justify-between"><div><b class="text-sm">Destino RPI</b><p class="text-[9px] text-gray-500">Se usa la misma IP guardada en GoldHen Manager.</p></div><button onclick="radarStore()" class="rounded-xl bg-violet-500/15 px-3 py-2 text-[10px] font-bold text-violet-200">⌁ Buscar PS4</button></div><div class="grid gap-2 sm:grid-cols-[1fr_150px_auto]"><input id="store-ip" inputmode="decimal" placeholder="IP de PS4" class="rounded-xl border border-white/10 bg-black/30 px-3 py-3 text-[12px] text-white outline-none focus:border-cyan-400"><select id="store-port" onchange="togglePuertoCustom()" class="rounded-xl border border-white/10 bg-black/30 px-3 py-3 text-[12px] text-white outline-none"><option value="12801">RPI · 12801</option><option value="12800">RPI · 12800</option><option value="custom">Otro puerto…</option></select><button onclick="guardarDestinoStore()" class="rounded-xl bg-cyan-400 px-4 py-3 text-[10px] font-black text-black">Guardar</button></div><input id="store-port-custom" type="number" min="1" max="65535" placeholder="Puerto personalizado" class="hidden mt-2 w-full rounded-xl border border-white/10 bg-black/30 px-3 py-3 text-[12px] text-white outline-none"><p id="store-destination-status" class="mt-2 text-[10px] text-gray-500"></p></section>
<div id="status" class="mb-3 text-xs text-gray-400"></div><section id="catalogo" class="grid grid-cols-2 gap-3 md:grid-cols-4"></section></main>
<div id="store-detail-modal" class="fixed inset-0 z-50 hidden items-end justify-center bg-black/75 p-4 sm:items-center" onclick="if(event.target===this)cerrarDetalleStore()"><article class="w-full max-w-lg max-h-[88dvh] overflow-y-auto rounded-3xl border border-white/10 bg-[#0a0f1a] p-5 shadow-2xl"><div class="mb-3 flex justify-end"><button onclick="cerrarDetalleStore()" class="h-9 w-9 rounded-xl bg-white/5 text-gray-300">✕</button></div><div id="store-detail-content"></div></article></div>
<script>
const api='../api/store_api.php';let catalogoStore=[];const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const bytes=n=>n?`${(n/1073741824).toFixed(2)} GB`:'peso no publicado';
async function peticion(action,extra={}){const f=new FormData();f.append('action',action);Object.entries(extra).forEach(([k,v])=>f.append(k,v));const r=await fetch(api,{method:'POST',body:f});return r.json();}function coverUrl(j){if(!j.cover)return '';const c=String(j.cover).replace(/^\.\//,'');if(c.startsWith('/'))return c;if(c.startsWith('store/covers/'))return `covers/${c.slice('store/covers/'.length)}`;return c}function puertoStore(){return document.getElementById('store-port').value==='custom'?document.getElementById('store-port-custom').value:document.getElementById('store-port').value}
function configurarDestinoStore(){const ip=localStorage.getItem('sebas_ip_final_libre')||'',p=localStorage.getItem('store_rpi_port')||'12801',s=document.getElementById('store-port');document.getElementById('store-ip').value=ip;s.value=['12800','12801'].includes(p)?p:'custom';document.getElementById('store-port-custom').value=['12800','12801'].includes(p)?'':p;togglePuertoCustom();document.getElementById('store-destination-status').textContent=ip?`IP compartida detectada: ${ip} · RPI ${p}`:'Configura la IP o usa Buscar PS4.';s.addEventListener('change',togglePuertoCustom)}function togglePuertoCustom(){document.getElementById('store-port-custom').classList.toggle('hidden',document.getElementById('store-port').value!=='custom')}
function guardarDestinoStore(){const ip=document.getElementById('store-ip').value.trim(),port=puertoStore(),status=document.getElementById('store-destination-status');if(!/^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/.test(ip)||!(+port>0&&+port<65536)){status.textContent='Indica una IP IPv4 y un puerto RPI válido.';return false}localStorage.setItem('sebas_ip_final_libre',ip);localStorage.setItem('store_rpi_port',port);status.textContent=`Destino guardado: ${ip} · RPI ${port}`;return true}
async function radarStore(){const status=document.getElementById('store-destination-status');status.textContent='Buscando una PS4 con FTP activo…';try{const d=await fetch('../api/radar_api.php?timeout=350&port=2121').then(r=>r.json());if(d.status==='success'&&d.ps4_ips?.length){document.getElementById('store-ip').value=d.ps4_ips[0];guardarDestinoStore()}else status.textContent='No se encontró una PS4. Confirma la red y GoldHEN.'}catch(_){status.textContent='No se pudo ejecutar el radar.'}}
function extras(j){return [j.enlaces?.update?'update':null,...(j.enlaces?.dlc||[]).map((_,i)=>`dlc:${i}`)].filter(Boolean)}function tarjeta(j){const c=coverUrl(j),img=c?`<img class="h-full w-full object-cover" src="${esc(c)}" onerror="this.style.display='none'">`:'';return `<article class="card overflow-hidden rounded-2xl border border-white/10 bg-white/5"><button onclick="abrirDetalleStore('${esc(j.id)}')" class="block w-full text-left"><div class="aspect-[3/4] bg-black/30">${img}</div><div class="p-3"><b class="block truncate text-sm">${esc(j.titulo)}</b><small class="text-cyan-300">${esc(j.id)} · v${esc(j.version||'1.00')}</small><p class="mt-2 text-xs text-gray-300">${esc(j.peso_gb??'?')} GB · ${esc(j.servidor||'Privado')}</p></div></button></article>`}
function abrirDetalleStore(id){const j=catalogoStore.find(x=>x.id===id);if(!j)return;const c=coverUrl(j),extra=extras(j),box=document.getElementById('store-detail-content');box.innerHTML=`${c?`<img class="mb-4 aspect-[16/9] w-full rounded-2xl object-cover bg-black/30" src="${esc(c)}" onerror="this.remove()">`:''}<h2 class="text-xl font-black">${esc(j.titulo)}</h2><p class="mt-1 text-xs text-cyan-300">${esc(j.id)} · ${esc(j.categoria||'PS4')} · v${esc(j.version||'1.00')}</p><p class="mt-4 text-sm leading-relaxed text-gray-300">${esc(j.descripcion||'Sin descripción publicada.')}</p><div class="mt-4 grid grid-cols-2 gap-2 text-xs"><span class="rounded-xl bg-white/5 p-3">Peso<br><b>${esc(j.peso_gb??'?')} GB</b></span><span class="rounded-xl bg-white/5 p-3">Proveedor<br><b>${esc(j.servidor||'Privado')}</b></span></div><div class="mt-5 grid gap-2"><button onclick="instalar('${esc(j.id)}','pkg',0)" class="rounded-xl bg-cyan-400 py-3 text-xs font-black text-black">Instalar paquete</button>${extra.map(x=>{const[k,i]=x.split(':');return `<button onclick="instalar('${esc(j.id)}','${k}',${i||0})" class="rounded-xl bg-white/10 py-3 text-xs">Instalar ${k.toUpperCase()}</button>`}).join('')}<button onclick="verificar('${esc(j.id)}')" class="py-2 text-xs text-gray-400">Verificar enlace</button></div>`;document.getElementById('store-detail-modal').classList.remove('hidden');document.getElementById('store-detail-modal').classList.add('flex')}function cerrarDetalleStore(){const m=document.getElementById('store-detail-modal');m.classList.add('hidden');m.classList.remove('flex')}
async function cargarCatalogo(){const s=document.getElementById('status'),box=document.getElementById('catalogo');s.textContent='Actualizando catálogo…';try{const d=await peticion('catalog');if(d.status!=='success')throw Error(d.message);catalogoStore=d.data||[];box.innerHTML=catalogoStore.length?catalogoStore.map(tarjeta).join(''):'<p class="text-gray-500">No hay elementos publicados.</p>';s.textContent=`${catalogoStore.length} elemento(s) publicado(s).`}catch(e){s.textContent=e.message||'No se pudo cargar el catálogo.'}}async function instalar(id,kind,index){if(!guardarDestinoStore())return;const d=await peticion('install',{id,kind,index,ip:document.getElementById('store-ip').value.trim(),port:puertoStore()});document.getElementById('status').textContent=d.message;if(d.status==='success')cerrarDetalleStore()}async function verificar(id){const d=await peticion('check',{id});document.getElementById('status').textContent=`${d.message}${d.size?` (${bytes(d.size)})`:''}`}configurarDestinoStore();cargarCatalogo();
</script></body></html>
